<script setup>
import {computed,onMounted,ref} from 'vue'
const tab=ref('dashboard'),loading=ref(false),dashboard=ref({}),orders=ref([]),providers=ref([]),services=ref([]),filter=ref('全部'),authenticated=ref(false),username=ref(''),password=ref(''),loginError=ref('')
const tabs=[['dashboard','工作台'],['orders','订单管理'],['providers','服务人员'],['services','服务项目']]
const base=import.meta.env.BASE_URL+'api/'
async function api(path,opts={}){const r=await fetch(base+path,{credentials:'same-origin',headers:{'Content-Type':'application/json'},...opts});if(r.status===401){authenticated.value=false;throw Error('请先登录管理端')}if(!r.ok)throw Error('请求失败');return r.json()}
async function login(){loginError.value='';try{await api('auth/login',{method:'POST',body:JSON.stringify({username:username.value,password:password.value})});authenticated.value=true;password.value='';await load()}catch{loginError.value='账号或密码错误'}}
async function load(){loading.value=true;try{dashboard.value=await api('admin/dashboard');orders.value=await api('admin/orders');providers.value=await api('admin/providers');services.value=await api('admin/services')}finally{loading.value=false}}
const filtered=computed(()=>filter.value==='全部'?orders.value:orders.value.filter(o=>o.status===filter.value))
async function status(o,s){await api(`admin/orders/${o.id}/status`,{method:'PATCH',body:JSON.stringify({status:s})});await load()}
async function accept(o){await api(`admin/orders/${o.id}/accept?providerId=1`,{method:'POST'});await load()}
onMounted(async()=>{try{authenticated.value=(await api('auth/me')).authenticated;if(authenticated.value)await load()}catch{authenticated.value=false}})
</script>
<template><div v-if="!authenticated" class="login-page"><form class="login-card" @submit.prevent="login"><div class="logo">太</div><p class="eyebrow">太禾行到家 · 运营中心</p><h1>管理端登录</h1><label>管理员账号<input v-model="username" autocomplete="username" required /></label><label>登录密码<input v-model="password" type="password" autocomplete="current-password" required /></label><p v-if="loginError" class="login-error">{{loginError}}</p><button class="primary">登录</button></form></div><div v-else class="shell"><aside><div class="brand"><div class="logo">太</div><div><b>太禾行</b><small>到家管理端</small></div></div><nav><button v-for="x in tabs" :key="x[0]" :class="{active:tab===x[0]}" @click="tab=x[0]">{{x[1]}}</button></nav><div class="aside-foot">平台运行正常<br/><span>Spring Boot API</span></div></aside><main><header><div><p class="eyebrow">太禾行到家 · 运营中心</p><h1>{{tabs.find(x=>x[0]===tab)?.[1]}}</h1></div><button class="refresh" @click="load">刷新数据</button></header><div v-if="loading" class="loading">正在加载...</div><section v-else-if="tab==='dashboard'"><div class="hero"><div><span>累计订单</span><strong>{{dashboard.totalOrders||0}}</strong><small>全平台</small></div><div><span>待处理订单</span><strong>{{dashboard.pendingOrders||0}}</strong><small>需要运营跟进</small></div><div><span>服务中</span><strong>{{dashboard.servingOrders||0}}</strong><small>当前履约</small></div><div><span>服务人员</span><strong>{{dashboard.providerCount||0}}</strong><small>已入驻</small></div></div><div class="grid two"><article class="card"><h2>订单状态</h2><div class="bars"><div v-for="s in ['待匹配','待接单','待上门','服务中','待结算','已完成']" :key="s"><span>{{s}}</span><i :style="{width:Math.max(8,orders.filter(o=>o.status===s).length/Math.max(1,orders.length)*100)+'%'}"></i><b>{{orders.filter(o=>o.status===s).length}}</b></div></div></article><article class="card"><h2>运营提醒</h2><p class="notice">新订单需要匹配服务人员，完成服务后请核验凭证并进入结算。</p><button class="primary" @click="tab='orders'">查看订单</button></article></div></section><section v-else-if="tab==='orders'" class="card"><div class="card-title"><div class="filters"><button v-for="s in ['全部','待匹配','待接单','待上门','服务中','待结算','已完成']" :key="s" :class="{chosen:filter===s}" @click="filter=s">{{s}}</button></div><span>{{filtered.length}} 条</span></div><div class="table-wrap"><table><thead><tr><th>订单号</th><th>服务项目</th><th>客户</th><th>预约时间</th><th>金额</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-for="o in filtered" :key="o.id"><td class="mono">{{o.orderNo}}</td><td><b>{{o.serviceName}}</b><small>{{o.address}}</small></td><td>{{o.customerName}}<small>{{o.phone}}</small></td><td>{{o.scheduledAt}}</td><td class="money">¥{{o.amount}}</td><td><em class="tag">{{o.status}}</em></td><td><button v-if="['待匹配','待接单'].includes(o.status)" class="mini primary" @click="accept(o)">匹配李阿姨</button><button v-else-if="o.status==='待上门'" class="mini" @click="status(o,'服务中')">开始服务</button><button v-else-if="o.status==='服务中'" class="mini" @click="status(o,'待结算')">提交结算</button><button v-else-if="o.status==='待结算'" class="mini" @click="status(o,'已完成')">确认完成</button><span v-else class="muted">已归档</span></td></tr></tbody></table></div></section><section v-else-if="tab==='providers'"><div class="provider-grid"><article v-for="p in providers" :key="p.id" class="provider card"><div class="avatar">{{p.name.slice(0,1)}}</div><div class="provider-main"><h2>{{p.name}} <em class="tag green">{{p.status}}</em></h2><p>信用分 {{p.creditScore}} · 已完成 {{p.completedOrders}} 单</p><div class="skills"><span v-for="s in p.skills" :key="s">{{s}}</span></div></div><button class="mini">查看资料</button></article></div></section><section v-else><div class="service-grid"><article v-for="s in services" :key="s.id" class="card service"><div class="service-image">{{s.category.slice(0,2)}}</div><div><span class="eyebrow">{{s.category}}</span><h2>{{s.name}}</h2><p>{{s.description}}</p><div class="service-bottom"><b>¥{{s.price}}<small>/次</small></b><span>{{s.durationHours}} 小时</span></div></div></article></div></section></main></div></template>
